// Generated by ts-rs from the Rust types the socket carries: change those and run `cargo test -p p02-gateway contract`.

/**
 * How much of a service: ordered, so `Write` satisfies a need for `Read`.
 */
export type AccessLevel = "none" | "read" | "write";

/**
 * What a plugin's manifest may request: a service the host hands it,
 * or a declaration of what it does.
 */
export type AccessName = "character_file_store" | "session_history" | "plugin_database" | "turn_context" | "model_input" | "trusted_context" | "network";

export type ActivationStatus = "active" | "disabled" | "blocked";

/**
 * What came of adding the character a file holds. `added`: she is new
 * here; `updated`: her package replaced the one installed. Either way her
 * package is on disk, and she starts as any enabled character does.
 */
export type AddCharacterOutcome = { "status": "added", characterId: Identifier, } | { "status": "updated", characterId: Identifier, } | { "status": "refused", reason: AddCharacterRefusal, message: string, } | { "status": "failed" } & StorageFailure;

export type AddCharacterRefusal = "invalid" | "built_in";

/**
 * The person's answer to a parked confirmation or a pairing request.
 */
export type Answer = "approved" | "denied";

/**
 * The person's answer, to a confirmation or a pairing request alike.
 */
export type AnswerBody = { decision: Answer, };

/**
 * What an answer to a parked confirmation came to. `expired`: the deadline
 * had passed, so the confirmation was settled cancelled instead; the
 * client is never the judge of the deadline.
 */
export type AnswerOutcome = { "status": "answered" } | { "status": "expired" } | { "status": "unknown" };

/**
 * An account of the person's that an app uses by a key: the id her phone
 * knows it by, its name, and whether the person gave her phone its key.
 */
export type AppAccount = { id: Identifier, name: string, hasKey: boolean, };

/**
 * A connection of the person's an app can sign in with: their service, by
 * the id the AI Model page knows it by, what that page calls it, the
 * models it offers, best first, and the one it asks until another is
 * chosen.
 */
export type AppConnection = { id: RoleModelProvider, name: string, models: ReadonlyArray<AppModel>, defaultModel: string, };

/**
 * What came of giving her an app, from the App Store or from a file: the
 * app as her phone now lists it, and the version of it that it replaced,
 * when it replaced one; or why it was not given.
 */
export type AppInstallOutcome = { "status": "ok", app: PhoneApp, replaced?: string, } | { "status": "refused", reason: AppInstallRefusal, message: string, } | { "status": "failed", message: string, };

/**
 * Why an app is not given to her: an app of the App Store, or one from a
 * file, which a preview of it says too.
 */
export type AppInstallRefusal = "unknown_character" | "no_phone" | "not_in_store" | "comes_with_phone" | "already_installed" | "not_as_listed" | "not_an_app";

/**
 * A model a connection offers: its id, and the name a person reads.
 */
export type AppModel = { id: string, name: string, };

/**
 * What an app's file would put on her phone, judged as adding it judges
 * it, with nothing written: what the app is, what it may do, a line each,
 * and the version of it on her phone that adding it replaces; or why the
 * file adds none.
 */
export type AppPreviewOutcome = { "status": "ok", id: Identifier, name: string, summary: string, icon: string, tint: string, version: string, wakes: boolean, itMay: ReadonlyArray<string>, replaces?: string, } | { "status": "refused", reason: AppInstallRefusal, message: string, } | { "status": "failed", message: string, };

/**
 * What came of removing an app from her phone: it is gone, with what it
 * kept and its rings; or why it was not removed.
 */
export type AppRemoveOutcome = { "status": "ok" } | { "status": "refused", reason: AppRemoveRefusal, message: string, } | { "status": "failed", message: string, };

export type AppRemoveRefusal = "unknown_character" | "no_phone" | "unknown_app" | "comes_with_phone";

/**
 * How an app that asks a model signs in on her phone: the connections of
 * the person's it can sign in with now, in the AI Model page's order, and
 * the one it is signed in with, while it is.
 */
export type AppSignIn = { connections: ReadonlyArray<AppConnection>, signedIn?: AppSignedIn, };

/**
 * The person's say on how an app that asks a model is signed in on her
 * phone: with `connection`, one of theirs connected now, asking `model`,
 * one it offers, or the one it starts with when none is named; with no
 * connection, it is signed out.
 */
export type AppSignInBody = { connection?: RoleModelProvider, model?: string, };

/**
 * What came of the person's say on how an app is signed in: it is kept;
 * or why it is not.
 */
export type AppSignInOutcome = { "status": "ok" } | { "status": "refused", reason: AppSignInRefusal, message: string, } | { "status": "failed", message: string, };

export type AppSignInRefusal = "unknown_character" | "no_phone" | "unknown_app" | "signs_in_to_nothing" | "not_connected" | "unknown_model";

/**
 * The connection an app is signed in with, and the model it asks: the
 * one the person chose, else the one its connection starts with.
 */
export type AppSignedIn = { connection: RoleModelProvider, model: string, };

/**
 * Where an app on her phone came from: it comes with her phone, it is the
 * App Store's, or the person added it from a file nobody read.
 */
export type AppSource = "built_in" | "catalog" | "file";

/**
 * A view of an app, which she opens it on: a tab, in the Clock.
 */
export type AppView = { id: Identifier, title: string, icon: string, };

/**
 * The person's say on whether an app may wake her.
 */
export type AppWakeBody = { allowed: boolean, };

/**
 * What came of the person's say on whether an app may wake her: it is
 * kept; or why it is not.
 */
export type AppWakeOutcome = { "status": "ok" } | { "status": "refused", reason: AppWakeRefusal, message: string, } | { "status": "failed", message: string, };

export type AppWakeRefusal = "unknown_character" | "no_phone" | "unknown_app" | "cannot_wake";

/**
 * What the target's own document holds for a field.
 */
export type Authored = { configured: boolean, value?: JsonValue, };

/**
 * How a bot stands. A bot that does not know yet is in no table.
 */
export type BotState = "on" | "refused" | "unreachable" | "conflict" | "webhook";

/**
 * The name a bot goes by on its connector's service, without the `@`: 1
 * to 32 ASCII letters, digits or underscores, as Telegram spells one.
 */
export type BotUsername = string;

/**
 * Whom a bubble's words are from: her, or the one she talks with there.
 */
export type BubbleFrom = "her" | "them";

/**
 * Why a change was refused.
 */
export type ChangeRefusal = "conflict" | "invalid" | "unknown_character";

export type CharacterConnectorEntry = { characterId: Identifier, activation: RuntimeConfigSectionActivationShape, values: { [key in string]: JsonValue }, };

/**
 * A feature a character would start with.
 */
export type CharacterFeature = { "kind": "plugin", id: Identifier, displayName: string, } | { "kind": "unknown", id: Identifier, };

/**
 * Whether the character a file holds is in the home already.
 */
export type CharacterInstalled = "none" | "same" | "other_version" | "built_in";

/**
 * Who a character file holds and what adding her would do, judged as an
 * add judges it, or why she cannot be added from it.
 */
export type CharacterPreviewOutcome = { "status": "ok", id: Identifier, displayName: SpeakerName, version: string, 
/**
 * One line about her, when her file has one.
 */
about?: string, 
/**
 * The features she would start with: each plugin on by default or
 * asked for by her file, in the plugin list's order, then each one
 * her file asks for that this build does not have.
 */
comesWith: ReadonlyArray<CharacterFeature>, installed: CharacterInstalled, 
/**
 * Whether a data folder of hers is in the home: she was here
 * before, and her chats come back with her.
 */
hasData: boolean, } | { "status": "refused", reason: CharacterPreviewRefusal, message: string, };

export type CharacterPreviewRefusal = "invalid";

/**
 * Where a character's runtime stands.
 */
export type CharacterRuntimeState = "starting" | "ready" | "needs_model" | "stopping" | "stopped" | "failed";

/**
 * One installed character, as health reports her.
 */
export type CharacterSummary = { id: Identifier, displayName: SpeakerName, enabled: boolean, 
/**
 * Whether she comes with the app: she can be switched off, never
 * removed.
 */
builtIn: boolean, state: RosterState, 
/**
 * Why she failed, what she needs for a model, or what her start
 * warned of.
 */
diagnostic?: string, 
/**
 * The latest background failure since she started.
 */
maintenance?: MaintenanceFailure, };

/**
 * What came of starting a sign-in, calling off its wait or signing out:
 * the sign-in as it then stands, or the sentence saying why it failed.
 */
export type ChatgptOutcome = { "status": "ok", signIn: ChatgptSignIn, } | { "status": "failed", message: string, };

/**
 * The home's sign-in to a ChatGPT plan as it stands.
 */
export type ChatgptSignIn = { "state": "signed_out", message?: string, } | { "state": "waiting", 
/**
 * The code the person types there.
 */
code: string, 
/**
 * Where they type it.
 */
url: string, 
/**
 * When the code stops working, in milliseconds since the Unix
 * epoch.
 */
expiresAt: number, } | { "state": "signed_in", email?: string, plan?: string, };

/**
 * What a client stamps on a line it carries: the surface it came from, or
 * the id it submitted the line under, which a repeat of the line reuses. An
 * ASCII letter or digit, then up to 63 ASCII letters, digits, `:`, `.`, `_`
 * or `-`.
 */
export type ClientStamp = string;

/**
 * What a finding is, in the one spelling clients read.
 */
export type Code = "runtime_config_unreadable" | "runtime_config_ignored" | "runtime_config_unknown_plugin" | "runtime_config_unknown_connector" | "runtime_config_value_invalid" | "runtime_config_authored_outside_scope" | "character_package_value_skipped" | "character_plugin_not_running";

/**
 * One change to one document, bound to the fingerprint its author read.
 */
export type ConfigChange = { target: ConfigTarget, expectedFingerprint: string, operation: Operation, };

/**
 * What came of a change. `Applied` means the document is on disk, under
 * the fingerprint it now has; `Refused` is the change itself, and
 * `Failed` a write that could not be made, either leaving every document
 * as it was.
 */
export type ConfigChangeOutcome = { "status": "applied", fingerprint: Fingerprint, } | { "status": "refused", reason: ChangeRefusal, message: string, } | { "status": "failed", message: string, };

export type ConfigHealth = { diagnostics: ReadonlyArray<RuntimeConfigDiagnostic>, };

/**
 * Whose settings a view reads or a change writes, and whose bot a
 * connector's is: the home's, or one character's.
 */
export type ConfigTarget = { "scope": "global" } | { "scope": "character", characterId: string, };

/**
 * The kind of value a config field holds. Whether it holds a
 * credential is the field's `secret` flag alone to say.
 */
export type ConfigValueType = "string" | "number" | "boolean" | "object" | "array" | "path" | "url" | "enum";

/**
 * What a settings screen renders: the fingerprint a change must present,
 * the diagnostics, whether the target's settings give a character an AI
 * model, the services she can think with, and the host's fields and every
 * section the target may set, all in one field shape. A target whose
 * settings cannot be resolved is refused with the reason, never shown as
 * blank fields.
 */
export type ConfigView = { "status": "ok", fingerprint: Fingerprint, diagnostics: ReadonlyArray<RuntimeConfigDiagnostic>, model: Setup, 
/**
 * Every service, in the order a page lists them.
 */
services: ReadonlyArray<ModelService>, project02: ReadonlyArray<RuntimeConfigFieldInspectShape>, sections: ReadonlyArray<RuntimeConfigSectionInspectShape>, } | { "status": "refused", reason: ViewRefusal, message: string, };

export type ConfirmationCancelReason = "expired" | "stopped";

/**
 * A parked confirmation's id: a fresh UUID, unique across the daemon, by
 * which any surface answers it.
 */
export type ConfirmationId = string;

/**
 * What the person is asked about: the plugin and tool whose call it is,
 * what the tool says it does, and what the call would do.
 */
export type ConfirmationQuestion = { pluginId: Identifier, toolName: Identifier, summary: string, preview: { [key in string]: JsonValue }, };

/**
 * How a confirmation ended: with the person's answer, or cancelled and
 * why.
 */
export type ConfirmationSettlement = { "decision": "approved" } | { "decision": "denied" } | { "decision": "cancelled", reason: ConfirmationCancelReason, };

/**
 * One bot a connector runs, as the connector says it stands: whose it is,
 * the home's own or one character's, the name it goes by once its service
 * has said who it is, and its state. Its token is no part of it.
 */
export type ConnectorBot = { target: ConfigTarget, username?: BotUsername, state: BotState, };

/**
 * A connector's bot table, whole every time: the daemon holds it in place
 * of the one it held, never beside it.
 */
export type ConnectorBotsBody = { bots: ReadonlyArray<ConnectorBot>, };

/**
 * What came of a connector's bot table. `kept`: health shows it from now
 * on, until the connector's last stream ends.
 */
export type ConnectorBotsOutcome = { "status": "kept" } | { "status": "refused", reason: ConnectorBotsRefusal, message: string, };

export type ConnectorBotsRefusal = "unknown_connector" | "not_connected";

/**
 * A connector's section for one target: its activation, and each field
 * that has a value it takes for that target, the home's fields reaching
 * every character's entry.
 */
export type ConnectorConfigEntry = { activation: RuntimeConfigSectionActivationShape, values: { [key in string]: JsonValue }, };

/**
 * What a connector runs on: an entry for the home and one for each
 * installed character that is switched on, in roster order, each with
 * its section's activation and, while that is active, the values in
 * effect for it, secrets in the clear. The home's switch is a default,
 * not a master switch: each entry is judged by its own.
 */
export type ConnectorConfigView = { "status": "ok", connectorId: Identifier, home: ConnectorConfigEntry, characters: ReadonlyArray<CharacterConnectorEntry>, } | { "status": "refused", reason: ConnectorRefusal, message: string, };

/**
 * Whether a process of a built-in connector is on the event stream now,
 * and the bots it last said it runs, none while it is not.
 */
export type ConnectorPresence = { id: Identifier, connected: boolean, bots: ReadonlyArray<ConnectorBot>, };

export type ConnectorRefusal = "unknown_connector" | "config_unloadable";

/**
 * A conversation: an ASCII letter or digit, then up to 55 ASCII letters,
 * digits, `_` or `-`. It holds no `.`, which is what parts it from the
 * segment number in the id of each of its sessions, and its length leaves
 * that id room for the segment within the 64 characters a tool admits.
 */
export type ConversationId = string;

/**
 * The value in effect: authored in a document, `config`; the declared
 * default, `default`; or none, `missing`. A refused value is in effect
 * unresolved, its value shown unless it is a secret's.
 */
export type EffectiveView = { name: Identifier, secret: boolean, source: ValueSource, resolved: boolean, value?: JsonValue, };

/**
 * A value's identity, comparable without the value: `sha256:` and the
 * lowercase hex SHA-256 of its [`canonical_json`].
 */
export type Fingerprint = string;

/**
 * The one shape every transport refusal takes; a verb's outcome never
 * uses it.
 */
export type GatewayErrorBody = { error: Refusal, };

/**
 * What every surface hears.
 */
export type GatewayEvent = { "kind": "turn_progress", characterId: Identifier, conversationId: ConversationId, progress: TurnProgress, } | { "kind": "turn_running" } & RunningTurn | { "kind": "turn_completed", characterId: Identifier, conversationId: ConversationId, 
/**
 * Absent for a turn of her own, which no line began.
 */
source?: ClientStamp, clientMessageId?: ClientStamp, status: TurnStatus, 
/**
 * Whether the line that began it is in the log; true for a turn of
 * her own, which has none: nothing of the person's waits on it.
 */
committed: boolean, reason?: string, message?: string, } | { "kind": "confirmation_requested" } & PendingConfirmation | { "kind": "confirmation_settled", characterId: Identifier, id: ConfirmationId, } & ({ "decision": "approved" } | { "decision": "denied" } | { "decision": "cancelled", reason: ConfirmationCancelReason, }) | { "kind": "pairing_requested" } & PairingRequest | { "kind": "pairing_settled", connectorId: Identifier, code: string, subject: PairingSubject, decision: PairingDecision, } | { "kind": "state_changed", characterId: Identifier, state: CharacterRuntimeState, 
/**
 * Present when a failure caused the change, or when she needs a
 * model: what to do about it.
 */
message?: string, } | { "kind": "health_changed", health: GatewayHealth, } | { "kind": "maintenance_failed", characterId: Identifier, at: Timestamp, message: string, } | { "kind": "phone_changed", characterId: Identifier, };

/**
 * The daemon's whole state in one read.
 */
export type GatewayHealth = { protocolVersion: 16, homeRoot: string, 
/**
 * What the home's settings document says of itself.
 */
config: ConfigHealth, 
/**
 * The packages discovery could not publish, which the roster lacks.
 */
packages: PackagesHealth, characters: ReadonlyArray<CharacterSummary>, connectors: ReadonlyArray<ConnectorPresence>, 
/**
 * The person's accounts her phone knows, which the home's settings
 * hold the keys of.
 */
accounts: ReadonlyArray<PersonAccount>, 
/**
 * The home's sign-in to a ChatGPT plan.
 */
chatgpt: ChatgptSignIn, };

/**
 * The person's line into one conversation, with the two stamps its client
 * puts on it: which surface carried it, and the id a repeat of the same
 * submission reuses.
 */
export type GatewayMessage = { conversationId: Short, text: Text, source: ClientStamp, clientMessageId: ClientStamp, };

/**
 * The first frame of a stream that cannot be caught up: the state every
 * later frame moves on from.
 */
export type GatewayReady = { protocolVersion: 16, health: GatewayHealth, confirmations: ReadonlyArray<PendingConfirmation>, pairings: ReadonlyArray<PairingRequest>, turns: ReadonlyArray<RunningTurn>, };

/**
 * Why a line was refused before any turn ran.
 */
export type GatewayRefusalReason = "unknown_conversation" | "character_unavailable" | "duplicate_submission";

/**
 * A committed message as the scrollback shows it, with the stamps its
 * client put on the person's line and when it was committed.
 */
export type HistoryMessage = { messageId: MessageId, role: VisibleMessageRole, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, committedAt: Timestamp, source?: ClientStamp, clientMessageId?: ClientStamp, };

/**
 * One page of a conversation's scrollback, chronological within the page;
 * `earlier` is the cursor of the page before it, while older messages
 * exist.
 */
export type HistoryOutcome = { "status": "ok", conversationId: ConversationId, characterId: Identifier, messages: ReadonlyArray<HistoryMessage>, earlier?: string, } | { "status": "refused", reason: HistoryRefusal, message: string, } | { "status": "failed" } & StorageFailure;

export type HistoryRefusal = "unknown_conversation" | "invalid_page";

/**
 * A Project02 identifier: an ASCII letter, then up to 127 ASCII letters,
 * digits, `.`, `_` or `-`. Characters, plugins and tools are named by one.
 */
export type Identifier = string;

export type JsonValue = number | string | boolean | ReadonlyArray<JsonValue> | { [key in string]: JsonValue } | null;

/**
 * One card of a section's layout: rows of its fields, under a title and
 * over a footer when it has them.
 */
export type LayoutCard = { title?: string, footer?: string, 
/**
 * Whether the card holds what most people leave as it is: a page may
 * keep a row of it out of sight while nothing sets its field.
 */
advanced: boolean, 
/**
 * When the card's rows have an effect.
 */
when?: LayoutWhen, rows: ReadonlyArray<LayoutRow>, };

/**
 * One row of a card: a field of the section.
 */
export type LayoutRow = { field: Identifier, 
/**
 * When the field has an effect, beyond its card's own condition.
 */
when?: LayoutWhen, };

/**
 * A condition on a field of the same section that lists its allowed
 * values: it holds while that field's value in effect is one of `is`.
 * What it guards has no effect otherwise, so a page may hide it then.
 */
export type LayoutWhen = { field: Identifier, is: ReadonlyArray<string>, };

/**
 * How a readout's reading moves, in milliseconds since the epoch.
 */
export type LiveReading = { "counts": "up", from: number, } | { "counts": "down", to: number, of: number, };

/**
 * A background failure the conversation never sees: the plugins' work
 * after a turn's commit, a segment rotation that failed, which the next
 * turn plans again, what closing a segment left undone, or what opening
 * her thread skipped because it could not be read.
 */
export type MaintenanceFailure = { at: Timestamp, message: string, };

/**
 * A message's place in its session: `<session id>:message-<n>`, numbered
 * from 1. Numbers climb but may skip, so a message's number is its order,
 * not a count.
 */
export type MessageId = string;

/**
 * A service as a settings page lists it: its name, what it is and where a
 * key for it comes from, whether it is connected and as whom, and which of
 * the host's fields are its own, its model's among them.
 */
export type ModelService = { id: RoleModelProvider, 
/**
 * What a page calls it.
 */
name: string, 
/**
 * What it is, in a line a page shows under its name.
 */
summary: string, 
/**
 * Where a key for it comes from, in a sentence; none for the ChatGPT
 * plan, which takes no key.
 */
keyFrom?: string, 
/**
 * Whether it is connected for the target: a credential of it in
 * effect, its key or for NVIDIA a server of the person's own too; for
 * the ChatGPT plan, the home signed in, which is no setting.
 */
connected: boolean, 
/**
 * Whom the ChatGPT plan is connected as, while the home is signed in.
 */
account?: PlanAccount, 
/**
 * The one of its fields that names the model she asks it for.
 */
model: Identifier, 
/**
 * Its own fields, in the order a page shows them.
 */
fields: ReadonlyArray<Identifier>, };

/**
 * The character whose thread with the person to open.
 */
export type OpenConversationBody = { characterId: Short, };

/**
 * What came of opening a character's thread with the person.
 */
export type OpenOutcome = { "status": "opened", conversationId: ConversationId, characterId: Identifier, } | { "status": "refused", reason: OpenRefusal, message: string, } | { "status": "failed" } & StorageFailure;

export type OpenRefusal = "character_unavailable";

/**
 * What a change does: sets or unsets a host field, by its path
 * `project02.<name>`; switches a section on or off, or leaves it to the
 * document beneath when `enabled` is absent; or sets or unsets one field
 * of a section.
 */
export type Operation = { "kind": "set", path: string, value: JsonValue, } | { "kind": "unset", path: string, } | { "kind": "section_enabled", namespace: RuntimeConfigSectionNamespace, id: string, enabled?: boolean, } | { "kind": "section_field_set", namespace: RuntimeConfigSectionNamespace, id: string, field: string, value: JsonValue, } | { "kind": "section_field_unset", namespace: RuntimeConfigSectionNamespace, id: string, field: string, };

export type Origin = { "scope": "character", characterId: Identifier, path: string, };

/**
 * A package discovery could not publish, and why, where.
 */
export type PackageReport = { message: string, path: string, };

export type PackagesHealth = { diagnostics: ReadonlyArray<PackageReport>, };

/**
 * How a pairing request ended: with the person's answer, or at its
 * deadline.
 */
export type PairingDecision = "approved" | "denied" | "expired";

export type PairingRefusal = "unknown_connector" | "config_unloadable";

/**
 * An account a connector asks to let in, waiting for the person's answer
 * under a code any surface shows and answers by, until it expires.
 */
export type PairingRequest = { connectorId: Identifier, 
/**
 * Six digits, unique among the requests waiting.
 */
code: string, subject: PairingSubject, 
/**
 * The connector's endpoint the account first wrote to, as the stamp
 * its lines will carry: for Telegram, `telegram:<bot username>`.
 */
source: ClientStamp, requestedAt: Timestamp, 
/**
 * When the request expires, in milliseconds since the Unix epoch.
 */
expiresAt: number, };

/**
 * The account a connector asks the person to let in, and where it wrote.
 */
export type PairingRequestBody = { subject: PairingSubjectBody, 
/**
 * The connector's endpoint the account wrote to, as the stamp its
 * lines will carry: for Telegram, `telegram:<bot username>`.
 */
source: ClientStamp, };

/**
 * What came of a connector's request to let an account in. `paired`: the
 * home lets it in already, so nothing is asked.
 */
export type PairingRequestOutcome = { "status": "pending", request: PairingRequest, } | { "status": "paired" } | { "status": "refused", reason: PairingRefusal, message: string, };

/**
 * What an answer to a pairing request came to. `expired`: the deadline had
 * passed, so the request was settled expired instead, as a confirmation
 * is; `failed`: the approval could not be written, and the request waits
 * on.
 */
export type PairingSettleOutcome = { "status": "settled", decision: Answer, } | { "status": "expired" } | { "status": "unknown" } | { "status": "failed", message: string, };

/**
 * The account a pairing is for: the connector's own id for it, and the
 * name the person sees.
 */
export type PairingSubject = { id: ClientStamp, label: SpeakerName, };

/**
 * The account a pairing is for: its id a stamp, and its name within the
 * bound of a name a person goes by, which the daemon judges further.
 */
export type PairingSubjectBody = { id: ClientStamp, label: Short, };

/**
 * A parked confirmation, as the stream announced it and the list shows it.
 */
export type PendingConfirmation = { characterId: Identifier, id: ConfirmationId, request: ConfirmationQuestion, 
/**
 * When the confirmation expires, in milliseconds since the Unix epoch.
 */
deadlineAt: number, 
/**
 * The turn that raised it; none for a call raised outside any turn.
 */
turn?: TurnIdentity, };

/**
 * An account of the person's at a service her apps may use: the id her
 * phone knows it by, its name, whether the person gave her phone its key,
 * and where a key comes from, in a sentence.
 */
export type PersonAccount = { id: Identifier, name: string, hasKey: boolean, keyFrom: string, };

/**
 * An app on her phone as her window draws it and her settings show it:
 * the line she knows it by, its version and where it came from; its icon
 * and the tint of its tile, names of the page's own set, which falls back
 * for one it does not know; whether it says it wakes her, and whether the
 * person lets it; what it may do, and the person's account it uses, or
 * how it signs in; its views, in its order; and the view it opens on.
 */
export type PhoneApp = { id: Identifier, name: string, summary: string, version: string, source: AppSource, icon: string, tint: string, 
/**
 * Whether it says it wakes her: only such an app sets a ring.
 */
wakes: boolean, 
/**
 * Whether the person lets it wake her: yes unless they said it may
 * not.
 */
mayWake: boolean, 
/**
 * What it may do, a line each, as the App Store says it.
 */
itMay: ReadonlyArray<string>, 
/**
 * The account of the person's it uses, when it uses one by a key.
 */
account?: AppAccount, 
/**
 * How it signs in, when it asks a model through a connection of the
 * person's.
 */
signIn?: AppSignIn, views: ReadonlyArray<AppView>, opensOn: Identifier, };

/**
 * What she last did on her phone: the app, a few words in the past tense,
 * and when.
 */
export type PhoneDid = { appId: Identifier, words: string, at: Timestamp, };

/**
 * The app and the view she has in front, and that view's screen, or,
 * when it cannot be shown, the sentence saying why in its place.
 */
export type PhoneFront = { appId: Identifier, viewId: Identifier, screen?: Screen, message?: string, };

/**
 * Her phone as it stands, read from her data whether she runs or not:
 * her apps, in her phone's order; what she has in front, none her home
 * screen; what she last did on it; and what rings, which nothing does but
 * while a ring's moment of hers runs.
 */
export type PhoneOutcome = { "status": "ok", apps: ReadonlyArray<PhoneApp>, front?: PhoneFront, did?: PhoneDid, ringing: ReadonlyArray<PhoneRing>, } | { "status": "refused", reason: PhoneRefusal, message: string, } | { "status": "failed", message: string, };

export type PhoneRefusal = "unknown_character" | "no_phone";

/**
 * A ring the moment of hers that runs now tells her: its app's name, its
 * title, its body when it has one, and the time it was set for.
 */
export type PhoneRing = { appName: string, title: string, body?: string, at: Timestamp, };

/**
 * Where a plugin's row belongs on a settings page.
 */
export type Placement = "mind_body" | "permission";

/**
 * The account a ChatGPT plan is signed in to: its email and its plan, such
 * as `plus`, as OpenAI named them.
 */
export type PlanAccount = { email?: string, plan?: string, };

/**
 * How a plugin's row on a settings page is drawn, as its manifest
 * declares it.
 */
export type PluginPage = { 
/**
 * The row's one-line subtitle.
 */
summary: string, 
/**
 * A name of the page's own set, as `tint` is: a page falls back for
 * one it does not know.
 */
icon: string, tint: string, placement: Placement, 
/**
 * Where the row comes among its placement's: by this, then by
 * display name.
 */
order: number, 
/**
 * What the plugin's entry among a page's connections is called, for
 * a plugin whose home settings are an account set up once.
 */
connection?: string, };

/**
 * A transport refusal: the envelope's code and sentence.
 */
export type Refusal = { code: string, message: string, };

/**
 * What came of removing a character. `removed`: her package is gone and
 * she stops; her data stays, for her to come back to.
 */
export type RemoveCharacterOutcome = { "status": "removed" } | { "status": "refused", reason: RemoveCharacterRefusal, message: string, } | { "status": "failed" } & StorageFailure;

export type RemoveCharacterRefusal = "built_in" | "unknown_character";

/**
 * The services a character can think with, each by the value of
 * `roleModelProvider` that chooses it, in the order a page lists
 * them. Only real services are here: the test provider is a test
 * harness's switch, never a setting, and a home has none until its
 * person chooses one.
 */
export type RoleModelProvider = "chatgpt" | "openai" | "anthropic" | "nvidia";

/**
 * Where an installed character stands as health reports her: her
 * runtime's state, or `not_started` until the daemon built it.
 */
export type RosterState = "not_started" | "starting" | "ready" | "needs_model" | "stopping" | "stopped" | "failed";

/**
 * A reply she is still writing: its text so far, under its draft's id.
 */
export type RunningDraft = { draftId: string, text: string, };

/**
 * A turn as it runs: her character, her thread, the stamps of the line
 * that began it, both or neither, and her drafts so far, each its whole
 * text, in the order they opened.
 */
export type RunningTurn = { characterId: Identifier, conversationId: ConversationId, 
/**
 * Absent for a turn of her own, which no line began.
 */
source?: ClientStamp, clientMessageId?: ClientStamp, drafts: ReadonlyArray<RunningDraft>, };

/**
 * A finding about the settings: its weight, its code, a sentence for a
 * person that never repeats a value, the place in the document, what it
 * concerns, the settings as a whole or one section, and, for a finding in
 * a character's overlay, whose.
 */
export type RuntimeConfigDiagnostic = { severity: Severity, code: Code, message: string, path?: string, origin?: Origin, } & ({ "scope": "global" } | { "scope": "section", namespace: RuntimeConfigSectionNamespace, id: string, field?: string, });

/**
 * One field as a screen shows it: its declaration, what the target's own
 * document holds for it, and the value in effect with where it comes
 * from, a secret's as `[redacted]`.
 */
export type RuntimeConfigFieldInspectShape = { name: Identifier, 
/**
 * What a page calls the field.
 */
label?: string, description: string, 
/**
 * What an empty box shows.
 */
placeholder?: string, secret: boolean, valueType?: ConfigValueType, allowedValues?: ReadonlyArray<string>, 
/**
 * The values a page offers first, while it takes any other of the
 * field's type too.
 */
suggestedValues?: ReadonlyArray<string>, 
/**
 * The words for each allowed or suggested value, which a page lists
 * in the order of `allowedValues` or `suggestedValues`.
 */
choices?: { [key in string]: string }, agentMutable: boolean, authored: Authored, effectiveSource: Source, effective: EffectiveView, };

/**
 * Whether a section runs, as its settings decide it, and why.
 */
export type RuntimeConfigSectionActivationShape = { enabled: boolean, status: ActivationStatus, reasons: ReadonlyArray<string>, };

/**
 * One section as a screen shows it.
 */
export type RuntimeConfigSectionInspectShape = { namespace: RuntimeConfigSectionNamespace, id: Identifier, displayName: string, version: string, 
/**
 * How a plugin's row is drawn, when its manifest says.
 */
page?: PluginPage, 
/**
 * What a plugin's manifest requests, each access with its level; a
 * connector has none.
 */
access?: { [key in AccessName]?: AccessLevel }, enabled: boolean, 
/**
 * Which document decides `enabled`, or the declaration's default.
 */
enabledSource: Source, activation: RuntimeConfigSectionActivationShape, 
/**
 * Whether its settings are enough to build it, judged switched on or
 * off: a plugin switched on before they are does not run. A
 * connector's always are.
 */
setup: Setup, fields: ReadonlyArray<RuntimeConfigFieldInspectShape>, 
/**
 * The cards `fields` are drawn in, each field in one at least.
 */
layout: ReadonlyArray<LayoutCard>, diagnostics: ReadonlyArray<RuntimeConfigDiagnostic>, };

/**
 * The two stanzas of a document that hold declared sections by id. A
 * plugin and a connector may share an id: their sections never meet.
 */
export type RuntimeConfigSectionNamespace = "plugins" | "connectors";

/**
 * What a view of an app shows: its pieces, top to bottom, and which page
 * of the view it is, when the view shows more than one.
 */
export type Screen = { items: ReadonlyArray<ScreenItem>, 
/**
 * Which page of its view this is, as the App Store's page of an app
 * says that app's id; none for a view of one page. One page's rows
 * are not another's.
 */
page?: string, };

/**
 * A cell of a strip: a small label over its value.
 */
export type ScreenCell = { label: string, value: string, };

/**
 * A piece of a screen.
 */
export type ScreenItem = { "kind": "list", header?: string, rows: ReadonlyArray<ScreenRow>, } | { "kind": "readout", 
/**
 * The thing's own id, which she passes to an action to change it.
 */
id?: string, label?: string, 
/**
 * The reading as of the call.
 */
text: string, caption?: string, 
/**
 * How the reading moves, when it does.
 */
live?: LiveReading, } | { "kind": "text", text: string, } | { "kind": "app", 
/**
 * The app's own id, which she passes to an action.
 */
id: string, tile: ScreenTile, name: string, subtitle: string, status: string, } | { "kind": "glance", title: string, 
/**
 * The reading, very large.
 */
text: string, 
/**
 * A line saying how it is.
 */
caption?: string, 
/**
 * A quieter line under the caption.
 */
detail?: string, } | { "kind": "strip", cells: ReadonlyArray<ScreenCell>, } | { "kind": "ranges", rows: ReadonlyArray<ScreenRange>, } | { "kind": "field", text: string, icon?: string, } | { "kind": "note", text: string, } | { "kind": "bubble", from: BubbleFrom, text: string, };

/**
 * One view of an app on her phone, as a person looking around it sees it:
 * its screen, or why there is none. Looking changes nothing of hers.
 */
export type ScreenOutcome = { "status": "ok", screen: Screen, } | { "status": "refused", reason: ScreenRefusal, message: string, } | { "status": "failed", message: string, };

/**
 * A row of ranges: its label, the words of its low and of its high, and
 * between them a bar from `from` to `to`, whole numbers from 0 to 100 on
 * the scale its rows share, `from` no greater than `to`.
 */
export type ScreenRange = { label: string, low: string, high: string, from: number, to: number, };

export type ScreenRefusal = "unknown_character" | "no_phone" | "unknown_app" | "unknown_view" | "app_failed";

/**
 * A row of a list: a title, a time or both.
 */
export type ScreenRow = { 
/**
 * The thing's own id, which she passes to an action to change it.
 */
id?: string, 
/**
 * An app's tile at the row's start.
 */
tile?: ScreenTile, 
/**
 * A small line above.
 */
caption?: string, title?: string, 
/**
 * A small line below.
 */
subtitle?: string, 
/**
 * A clock reading, shown large.
 */
time?: string, 
/**
 * Plain text at the row's end.
 */
value?: string, 
/**
 * A switch, shown on or off.
 */
switch?: boolean, 
/**
 * The address of the page the row is about, `https://` or `http://`
 * and 2,048 characters at most: its title is drawn as a link.
 */
url?: string, };

/**
 * An app's tile as a screen draws it: its icon and its tint, names of the
 * page's own set, as an app's on her home screen are.
 */
export type ScreenTile = { icon: string, tint: string, };

/**
 * Whether settings are enough for what they set up, a plugin or a
 * character's AI model; while they are not, `message` says what to fill
 * in, in the words of the settings page.
 */
export type Setup = { ready: boolean, message?: string, };

/**
 * How much a finding weighs: an error stops what it concerns, a warning
 * only says so.
 */
export type Severity = "warning" | "error";

/**
 * A string of 1 to 128 characters, as an id is on the wire, and the name
 * an account goes by.
 */
export type Short = string;

/**
 * Where a value in effect comes from: its field's declared default, the
 * home's settings, or the character's own.
 */
export type Source = "default" | "global" | "character";

/**
 * The name a speaker goes by on a message: one line of at most 128
 * characters, without blank space at either end. It is set before a
 * colon in chat, which is why a line break is refused.
 */
export type SpeakerName = string;

/**
 * What an explicit start came to: `settled` says it ran, and the summary's
 * state says how it ended.
 */
export type StartOutcome = { "status": "settled", character: CharacterSummary, } | { "status": "refused", reason: StartRefusal, message: string, };

export type StartRefusal = "unknown_character" | "gateway_stopped";

/**
 * An ordinary failure of the home's storage, a full disk, a permission or
 * a damaged record, which the person is told and which is no bug.
 */
export type StorageFailure = { code: string, message: string, };

/**
 * An app of the App Store as its page there says it: its tile, its
 * version and what changed in it, whether it says it wakes her, what it
 * may do, a line each, and how it stands on her phone.
 */
export type StoreApp = { id: Identifier, name: string, summary: string, icon: string, tint: string, version: string, changes: string, wakes: boolean, itMay: ReadonlyArray<string>, status: StoreAppStatus, };

/**
 * How an app of the App Store stands on her phone, versions ordered as
 * their three numbers: not on it; on it in an older version than the
 * store's, which the store's updates; or on it in the store's version or
 * a newer one.
 */
export type StoreAppStatus = "not_on_phone" | "update" | "installed";

/**
 * The App Store's catalog as the person browses it for her, read anew:
 * each app as its page in the store says it, with the version of it on
 * her phone; or why it could not be read.
 */
export type StoreOutcome = { "status": "ok", apps: ReadonlyArray<StoreApp>, } | { "status": "refused", reason: PhoneRefusal, message: string, } | { "status": "failed", message: string, };

/**
 * What became of a line sent to a character: queued in her inbox, where
 * she takes it in its turn and the stream tells how that ended, or
 * refused at once.
 */
export type SubmitOutcome = { "status": "queued" } | { "status": "already_queued" } | { "status": "refused", reason: GatewayRefusalReason, message: string, } | { "status": "failed" } & StorageFailure;

/**
 * A line's text, as long as a line may be.
 */
export type Text = string;

/**
 * A moment, in the one spelling every record uses: UTC to the
 * millisecond, `2026-06-15T00:00:00.000Z`. Text order is time order.
 */
export type Timestamp = string;

/**
 * How a call of a round came back: as its plugin answered, or refused.
 */
export type ToolCallStatus = "accepted" | "rejected";

/**
 * The submission a turn runs for, which any surface can tell as its own.
 */
export type TurnIdentity = { conversationId: ConversationId, source: ClientStamp, clientMessageId: ClientStamp, };

/**
 * What a turn says as it goes, in order.
 */
export type TurnProgress = { "kind": "user_message", messageId: MessageId, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, source: ClientStamp, clientMessageId: ClientStamp, } | { "kind": "visible_reply", messageId: MessageId, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, 
/**
 * The draft this message replaces.
 */
draftId: string, } | { "kind": "tool_calls_requested", round: number, toolNames: ReadonlyArray<Identifier>, } | { "kind": "tool_call_completed", round: number, status: ToolCallStatus, 
/**
 * The plugin that provides the tool, or `undeclared.<tool>` for a
 * tool the turn did not offer.
 */
pluginId: Identifier, toolName: Identifier, };

/**
 * How a turn ended, as the frame announcing it says.
 */
export type TurnStatus = "completed" | "rejected" | "refused" | "failed";

export type ValueSource = "config" | "default" | "missing";

export type ViewRefusal = "unknown_character" | "config_unloadable";

/**
 * Which side of a conversation someone speaks for: a character, or the
 * person. A visible message carries its speaker's, and the two order as
 * they are spelled, characters first.
 */
export type VisibleMessageRole = "character" | "user";

/**
 * Text as a person sees it: line endings are `\n`, neither end is blank
 * space, and something is left.
 */
export type VisibleText = string;
